import {validatePassword,parseVerificationLink} from './auth-utils.js';
const SDK='https://www.gstatic.com/firebasejs/12.4.0/';
export async function connectFirebase(config,onUser){
 const [appSDK,authSDK,dbSDK]=await Promise.all([import(SDK+'firebase-app.js'),import(SDK+'firebase-auth.js'),import(SDK+'firebase-firestore.js')]);
 const {initializeApp,getApps}=appSDK;
 const {getAuth,onIdTokenChanged,signInWithEmailAndPassword,createUserWithEmailAndPassword,signOut,sendPasswordResetEmail,sendEmailVerification,updateProfile,reload,getIdToken,setPersistence,browserSessionPersistence,browserLocalPersistence,GoogleAuthProvider,signInWithPopup,checkActionCode,applyActionCode,verifyPasswordResetCode,confirmPasswordReset,connectAuthEmulator}=authSDK;
 const {getFirestore,doc,getDoc,setDoc,collection,getDocs,writeBatch,deleteDoc,connectFirestoreEmulator}=dbSDK;
 const emulated=['localhost','127.0.0.1'].includes(location.hostname)&&new URLSearchParams(location.search).get('emulators')==='1';
 const appConfig=emulated?{projectId:'demo-bloom',apiKey:'demo-bloom-key',authDomain:'demo-bloom.firebaseapp.com',appId:'1:123:web:bloom'}:config;
 const app=getApps().find(a=>a.options.projectId===appConfig.projectId)||initializeApp(appConfig,appConfig.projectId),auth=getAuth(app),db=getFirestore(app);
 if(emulated){connectAuthEmulator(auth,'http://127.0.0.1:9199',{disableWarnings:true});connectFirestoreEmulator(db,'127.0.0.1',8180);}
 const actionSettings={url:emulated?location.origin+'/?emulators=1':location.origin,handleCodeInApp:false};
 const requireVerified=(expectedUid)=>{const u=auth.currentUser;if(!u?.emailVerified||expectedUid&&u.uid!==expectedUid)throw Error('Verify your email before syncing your space.');return u;};
 const client={get user(){return auth.currentUser;},pendingState:null,
 async loadState(){const user=requireVerified();const snap=await getDoc(doc(db,'users',user.uid,'data','bloom'));return snap.exists()?snap.data().state:null;},
 async saveState(state,expectedUid){const userId=requireVerified(expectedUid).uid;await setDoc(doc(db,'users',userId,'data','bloom'),{state,updatedAt:new Date().toISOString()});const reminders=collection(db,'users',userId,'reminders'),existing=await getDocs(reminders);const upcoming=state.settings.notifications?state.tasks.filter(t=>!t.done&&t.reminder).map(t=>({...t,dueAt:new Date(`${t.date}T${t.reminder}`).getTime()})).filter(t=>t.dueAt>Date.now()-10*60*1000):[];const valid=new Set(upcoming.map(t=>t.id));let batch=writeBatch(db),ops=0;for(const d of existing.docs){if(!valid.has(d.id)){batch.delete(d.ref);ops++;}if(ops===400){await batch.commit();batch=writeBatch(db);ops=0;}}for(const t of upcoming){batch.set(doc(reminders,t.id),{title:t.title,dueAt:t.dueAt,taskId:t.id,url:location.origin});ops++;if(ops===400){await batch.commit();batch=writeBatch(db);ops=0;}}if(ops)await batch.commit();},
 async authenticate(email,password,create,{name='',remember=false}={}){if(create)validatePassword(password);await setPersistence(auth,remember?browserLocalPersistence:browserSessionPersistence);if(!create)return signInWithEmailAndPassword(auth,email.trim(),password);const result=await createUserWithEmailAndPassword(auth,email.trim(),password);await updateProfile(result.user,{displayName:name.trim().slice(0,40)});let verificationSent=false;try{await sendEmailVerification(result.user,actionSettings);verificationSent=true;}catch{}return {...result,verificationSent};},
 async googleSignIn(remember=false){await setPersistence(auth,remember?browserLocalPersistence:browserSessionPersistence);const provider=new GoogleAuthProvider();provider.setCustomParameters({prompt:'select_account'});return signInWithPopup(auth,provider);},
 resetPassword:email=>sendPasswordResetEmail(auth,email.trim(),actionSettings),
 async sendVerification(){if(!auth.currentUser)throw Error('Sign in again to request a verification email.');await sendEmailVerification(auth.currentUser,actionSettings);},
 async refreshUser(){if(!auth.currentUser)return null;await reload(auth.currentUser);await getIdToken(auth.currentUser,true);return auth.currentUser;},
 async verifyLink(input){const user=auth.currentUser;if(!user)throw Error('Sign in before verifying your email.');const action=parseVerificationLink(input,location.origin,config.authDomain),info=await checkActionCode(auth,action.code);if(info.operation!=='VERIFY_EMAIL'||info.data.email?.toLowerCase()!==user.email?.toLowerCase())throw Error('This verification link belongs to another email account.');if(auth.currentUser?.uid!==user.uid)throw Error('Your account changed. Please sign in again.');await applyActionCode(auth,action.code);return client.refreshUser();},
 async inspectAction(action){if(action.mode==='resetPassword')return {email:await verifyPasswordResetCode(auth,action.code)};const info=await checkActionCode(auth,action.code);const expected={verifyEmail:'VERIFY_EMAIL',recoverEmail:'RECOVER_EMAIL'};if(info.operation!==expected[action.mode])throw Error('This email link does not match the requested action.');if(action.mode==='verifyEmail'){await applyActionCode(auth,action.code);if(auth.currentUser)await client.refreshUser();}return {email:info.data.email};},
 async completeReset(code,password){validatePassword(password);await confirmPasswordReset(auth,code,password);},
 async signOut(){try{const key=localStorage.getItem('bloom-device-id');if(key&&auth.currentUser?.emailVerified)await deleteDoc(doc(db,'users',auth.currentUser.uid,'devices',key));}catch{}await signOut(auth);},
 async enableMessaging(vapidKey){const {getMessaging,getToken,isSupported}=await import(SDK+'firebase-messaging.js');if(!await isSupported())throw Error('Messaging is not supported.');const reg=await navigator.serviceWorker.ready;const token=await getToken(getMessaging(app),{vapidKey,serviceWorkerRegistration:reg});if(!token)throw Error('No notification token.');let id=localStorage.getItem('bloom-device-id');if(!id){id=crypto.randomUUID();localStorage.setItem('bloom-device-id',id);}await setDoc(doc(db,'users',requireVerified().uid,'devices',id),{token,updatedAt:Date.now()});return token;}
 };
 const unsubscribe=onIdTokenChanged(auth,user=>setTimeout(()=>onUser(user),0));client.dispose=unsubscribe;return client;
}
